const MARKER = '{Y>>> {RHIDDEN{Y: something concealed in this room <<<{x\n';

const state = (globalThis.__saHiddenRoom ??= { inBlock: false });
const payload = (event && event.payload) || {};
const chunk = String(payload.rawText ?? payload.text ?? '');

const lines = chunk.split('\n');
if (lines[lines.length - 1] === '') lines.pop();

for (const raw of lines) {
  const plain = raw.replace(/\x1b\[[0-9;?]*[A-Za-z]/g, '').replace(/\r/g, '');

  if (/^ ?\[Exits:/.test(plain)) {
    state.inBlock = true;
    continue;
  }
  if (!state.inBlock) continue;

  if (plain === '' || /^<\d+\/\d+hp/.test(plain)) {
    state.inBlock = false;
    continue;
  }
  if (/^ {5}$/.test(plain)) {
    writeTerminal(MARKER);
  }
}
